-- Additive migration: preserves all existing owner, project, memory, conversation, and message data.
CREATE TABLE IF NOT EXISTS nova_execution_runs (id text PRIMARY KEY,owner_id text NOT NULL REFERENCES nova_owners(id) ON DELETE CASCADE,project_id text REFERENCES nova_projects(id) ON DELETE SET NULL,conversation_id text REFERENCES nova_conversations(id) ON DELETE SET NULL,goal text NOT NULL,status text NOT NULL,current_step integer NOT NULL DEFAULT 0,result jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
