CREATE TABLE IF NOT EXISTS nova_approvals (id text PRIMARY KEY,owner_id text NOT NULL REFERENCES nova_owners(id) ON DELETE CASCADE,project_id text REFERENCES nova_projects(id) ON DELETE SET NULL,run_id text REFERENCES nova_execution_runs(id) ON DELETE SET NULL,tool text NOT NULL,reason text NOT NULL,risk_level text NOT NULL,arguments jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'pending',decision text,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz);
