CREATE TABLE IF NOT EXISTS nova_activity_events (sequence bigserial PRIMARY KEY,id text UNIQUE NOT NULL,owner_id text NOT NULL REFERENCES nova_owners(id) ON DELETE CASCADE,project_id text REFERENCES nova_projects(id) ON DELETE SET NULL,run_id text REFERENCES nova_execution_runs(id) ON DELETE SET NULL,action text NOT NULL,tool text,status text NOT NULL,summary text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
